L["nobody to buff right now."] = "nessuno a cui dare un beneficio per ora."
L["|cffff8080that may still have cast|r -- the prompt cannot be disarmed in combat, and nothing was recorded for it."] = "|cffff8080potrebbe aver lanciato comunque|r -- il riquadro non si può disarmare in combattimento, e non è stato registrato nulla."
L["nobody to skip right now."] = "nessuno da saltare per ora."
L["skipping |cffffffff%s|r for now."] = "salto |cffffffff%s|r per ora."
L["held back -- the cooldown was still running"] = "trattenuto -- il tempo di recupero era ancora in corso"
L["Buffed you -- return the favour."] = "Ti ha dato un beneficio -- ricambia il favore."
L["In your group, and theirs is running out."] = "Nel tuo gruppo, e il suo beneficio sta per scadere."
L["Your target, and theirs is running out."] = "Il tuo bersaglio, e il suo beneficio sta per scadere."
L["Nearby, and theirs is running out."] = "Vicino, e il suo beneficio sta per scadere."
L["In your group and missing it."] = "Nel tuo gruppo, e non ce l'ha."
L["Your target, and missing it."] = "Il tuo bersaglio, e non ce l'ha."
